@RunWith(MockitoJUnitRunner.class)
public class JsonWriter_nullValue_TriageGen0Test {

    @Test
    public void testNullValue_DeferredNameNull_SerializeNullsFalse() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(mock(Writer.class));
        jsonWriter.deferredName = null;
        jsonWriter.serializeNulls = false;
        jsonWriter.nullValue();
        verify(jsonWriter).deferredName = null;
        assertNull(jsonWriter.deferredName);
        verify(jsonWriter).beforeValue(false);
        verify(jsonWriter).out.write("null");
    }

    @Test
    public void testNullValue_DeferredNameNull_SerializeNullsTrue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(mock(Writer.class));
        jsonWriter.deferredName = null;
        jsonWriter.serializeNulls = true;
        jsonWriter.nullValue();
        verify(jsonWriter).deferredName = null;
        assertNull(jsonWriter.deferredName);
        verify(jsonWriter).beforeValue(false);
        verify(jsonWriter).writeDeferredName();
        verify(jsonWriter).out.write("null");
    }

